CREATE PROCEDURE SpGetJobsList
	@userID int = null,
	@condition nvarchar(MAX)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Query NVARCHAR(MAX)
		SET @Query = 'Select constants_id, constants_name, constants_name_1, constants_name_2, CASE WHEN constants_name_3= ''error'' THEN ''ERROR'' ELSE ''SUCCESS'' END AS constants_name_3, constants_name_4, idate from constants c WHERE duser IS NULL AND ddate IS NULL ' + @condition
	EXECUTE sp_executesql @Query
END

